117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        // Normalize the address up front so every downstream use (the required-field check,
121	        // household-duplicate detection, the shared household id and the stored/returned value)
122	        // works from the same canonical form.
123	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
124	        List<String> missingFields = new ArrayList<>();
125	        if (isBlank(ownerFieldsDto.getFirstName())) {
126	            missingFields.add("firstName");
127	        }
128	        if (isBlank(ownerFieldsDto.getLastName())) {
129	            missingFields.add("lastName");
130	        }
131	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
132	        if (isBlank(normalizedAddress)) {
133	            missingFields.add("address");
134	        }
135	        if (isBlank(ownerFieldsDto.getCity())) {
136	            missingFields.add("city");
137	        }
138	        if (isBlank(ownerFieldsDto.getTelephone())) {
139	            missingFields.add("telephone");
140	        }
141	        if (!missingFields.isEmpty()) {
142	            throw new InvalidOwnerFieldsException(missingFields);
143	        }
144	        // A supplied registration date may not lie in the future: reject with 400 when the caller
145	        // provides a date later than the server's current date. Checked against the raw supplied value
146	        // (before any business-day adjustment) so a future date is never silently accepted.
147	        if (ownerFieldsDto.getRegistrationDate() != null
148	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
149	            throw new FutureRegistrationDateException(ownerFieldsDto.getRegistrationDate());
150	        }
151	        // Determine the effective registration date up front so every downstream use (the daily
152	        // create-limit, the stored value and anything derived from it such as the membership number's
153	        // year segment) works from the same business-day-adjusted date. The effective date is the
154	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
155	        // forward to the following Monday.
156	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
157	            ? ownerFieldsDto.getRegistrationDate()
158	            : LocalDate.now();
159	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
160	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
161	        // already carry this adjusted business day's registration date, no further owners may be
162	        // created for that day.
163	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
164	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
165	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
166	        }
167	        // Flag a bulk signup once more than 80 owners have already been created for this
168	        // business day, sharing the same daily accumulation path as the create-limit rule above.
169	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
170	        // Reject the request when the owner's city is already full: a city that already holds the
171	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
172	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
173	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
174	        }
175	        // Postcode is optional; when present it must be a 4-digit value that is valid for the
176	        // owner's city per the fixed region ranges. A malformed or out-of-range postcode is
177	        // rejected with a 400. An absent postcode leaves the request contract unchanged.
178	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
179	        // Normalize the telephone into E.164 form; a number that cannot form a valid
180	        // E.164 value is rejected with a 400.
181	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
182	        // Email is optional; when present it must be a syntactically valid address and is
183	        // stored lower-cased. An invalid address is rejected with a 400.
184	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
185	        // Derive the household id up front. It is a deterministic function of the normalized last name
186	        // and the postcode, so owners sharing a last name and postcode independently derive the same
187	        // value and are the same household. It is always computed (never null), regardless of whether
188	        // the caller opts into a shared household; 'sharesHousehold' now only bypasses the household
189	        // duplicate block below.
190	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
191	        String householdId = householdId(normalizedLastName, ownerFieldsDto.getPostcode());
192	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
193	        // All duplicate detection is consolidated into a single derived identity key:
194	        // 'normalizedTelephone + | + (email or empty) + | + householdId'. Because the telephone is
195	        // part of the key, two members of the same household (same householdId) with different
196	        // telephones have different keys and are both allowed; only an exact whole-key match is a
197	        // duplicate. Reject with 409 when a new owner's whole identity key equals an existing one's.
198	        String identityKey = identityKey(normalizedTelephone, normalizedEmail, householdId);
199	        boolean identityInUse = this.clinicService.findAllOwners().stream()
200	            .anyMatch(existing -> identityKey.equals(
201	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
202	        if (identityInUse) {
203	            throw new DuplicateOwnerIdentityException(identityKey);
204	        }
205	        // Because the household is keyed on (last name, postcode), any existing owner carrying this
206	        // computed household id is already a member of this household. A second such owner is rejected
207	        // as a household duplicate (409) unless the caller declares 'sharesHousehold', which bypasses
208	        // the block and admits the owner as a declared household member.
209	        boolean householdMemberExists = this.clinicService.findAllOwners().stream()
210	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
211	        if (householdMemberExists && !sharesHousehold) {
212	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), normalizedAddress);
213	        }
214	        HttpHeaders headers = new HttpHeaders();
215	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
216	        owner.setAddress(normalizedAddress);
217	        owner.setTelephone(normalizedTelephone);
218	        owner.setEmail(normalizedEmail);
219	        owner.setHouseholdId(householdId);
220	        // Record how many existing owners (before this create) share this owner's first and last
221	        // name, compared case-insensitively. Computed against the current owners so the new owner
222	        // itself is never counted.
223	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
224	        // Record the size of this owner's household (owners sharing the same householdId) after this
225	        // create: the existing members already stamped with the shared identifier plus this new
226	        // owner. An owner not admitted into any household is a household of one.
227	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
228	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
229	        owner.setBulkSignupWarning(bulkSignupWarning);
230	        // Store the business-day-adjusted effective registration date computed above. This defaults
231	        // to the server's current date when none was supplied and rolls any weekend date forward to
232	        // the following Monday, so everything derived from it (e.g. the membership number's year
233	        // segment) uses the adjusted date.
234	        owner.setRegistrationDate(effectiveRegistrationDate);
235	        // Assign the customer code: '<REGION>-<HASH8>' where REGION is the region derived from the
236	        // owner's postcode (falling back to the city-to-region table, else 'UNKNOWN', matching the
237	        // locality derivation) and HASH8 is the first 8 upper-case hex characters of
238	        // SHA-256(normalizedTelephone + lastName). Sequence numbers are no longer used.
239	        owner.setCustomerCode(customerCode(
240	            deriveRegion(owner.getPostcode(), owner.getCity()), normalizedTelephone, owner.getLastName()));
241	        // Soft-match detection: an owner that cleared the hard-duplicate checks above may still
242	        // resemble an existing owner when it shares that owner's last name and postcode but carries a
243	        // different telephone. A declared household member ('sharesHousehold') is never a suspected
244	        // duplicate, so it is exempt; any other owner reaching here shares no household with an
245	        // existing owner (a household match without 'sharesHousehold' was already rejected above).
246	        // Flag a matched owner as a possible duplicate, recording its id; otherwise the flag is false
247	        // with no matched id.
248	        Owner possibleDuplicateOwner = sharesHousehold ? null : findPossibleDuplicate(
249	            owner.getLastName(), owner.getPostcode(), normalizedTelephone);
250	        owner.setPossibleDuplicate(possibleDuplicateOwner != null);
251	        owner.setPossibleDuplicateOf(possibleDuplicateOwner == null ? null : possibleDuplicateOwner.getId());
252	        this.clinicService.saveOwner(owner);
253	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
254	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
255	        // customer code, the effective registration date and the numeric membership level.
256	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
257	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
258	        headers.setLocation(UriComponentsBuilder.newInstance()
259	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
260	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
261	    }
