356	
357	    private static boolean isBlank(String value) {
358	        return value == null || value.trim().isEmpty();
359	    }
360	
361	    /**
362	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
363	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
364	     * compared case-insensitively with collapsed whitespace.
365	     */
366	    private static String collapse(String value) {
367	        if (value == null) {
368	            return "";
369	        }
370	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
371	    }
372	
373	    /**
374	     * Common street-type abbreviations expanded during address normalization.
375	     */
376	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
377	        "ST", "STREET",
378	        "RD", "ROAD",
379	        "AVE", "AVENUE");
380	
381	    /**
382	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
383	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
384	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
385	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
386	     * address maps to itself.
387	     */
388	    private static String normalizeAddress(String value) {
389	        if (value == null) {
390	            return "";
391	        }
392	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
393	        if (collapsed.isEmpty()) {
394	            return "";
395	        }
396	        String[] tokens = collapsed.split(" ");
397	        StringBuilder sb = new StringBuilder(collapsed.length());
398	        for (int i = 0; i < tokens.length; i++) {
399	            if (i > 0) {
400	                sb.append(' ');
401	            }
402	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
403	        }
404	        return sb.toString();
405	    }
406	
407	    /**
408	     * Derive the stable household identifier shared by owners with the same normalized last name
409	     * and postcode. It is a deterministic function of those two values, so every member of a
410	     * household independently derives the same identifier: the first 12 upper-case hex characters
411	     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
412	     * an empty segment.
413	     */
414	    private static String householdId(String normalizedLastName, String postcode) {
415	        try {
416	            byte[] digest = MessageDigest.getInstance("SHA-256")
417	                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
418	                    .getBytes(StandardCharsets.UTF_8));
419	            StringBuilder sb = new StringBuilder(digest.length * 2);
420	            for (byte b : digest) {
421	                sb.append(String.format("%02x", b));
422	            }
423	            return sb.substring(0, 12).toUpperCase();
424	        }
425	        catch (NoSuchAlgorithmException e) {
426	            throw new IllegalStateException("SHA-256 not available", e);
427	        }
428	    }
429	
430	    /**
431	     * Derive the identity key into which all duplicate detection is consolidated:
432	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
433	     * household id contributes an empty segment. Two owners are duplicates only when their whole
434	     * identity keys are equal.
435	     */
436	    private static String identityKey(String telephone, String email, String householdId) {
437	        return (telephone == null ? "" : telephone)
438	            + "|" + (email == null ? "" : email)
439	            + "|" + (householdId == null ? "" : householdId);
440	    }
441	
442	    /**
443	     * Count the existing owners that share the given first and last name, compared
444	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
445	     * namesakes that already existed at creation time (the new owner itself is not included).
446	     */
447	    private int countNamesakes(String firstName, String lastName) {
448	        return (int) this.clinicService.findAllOwners().stream()
449	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
450	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
451	                && existing.getLastName().equalsIgnoreCase(lastName))
452	            .count();
453	    }
454	
455	    /**
456	     * Count the existing owners that already belong to the given household (i.e. carry the same
457	     * non-null householdId). Called after any existing members have been backfilled with the shared
458	     * identifier but before the new owner is saved, so the returned value reflects the members that
459	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
460	     * new owner is not part of any household ({@code householdId} is null).
461	     */
462	    private int countHouseholdMembers(String householdId) {
463	        if (householdId == null) {
464	            return 0;
465	        }
466	        return (int) this.clinicService.findAllOwners().stream()
467	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
468	            .count();
469	    }
470	
471	    /**
472	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one that shares
473	     * the new owner's last name (compared case-insensitively) and postcode while carrying a different
474	     * (already normalized) telephone. When several existing owners match, the earliest (lowest id) is
475	     * returned so the result is deterministic. Returns {@code null} when there is no such owner —
476	     * including when the new owner has no last name or postcode, since a shared postcode is required
477	     * to match.
478	     */
479	    private Owner findPossibleDuplicate(String lastName, String postcode, String normalizedTelephone) {
480	        if (isBlank(lastName) || isBlank(postcode)) {
481	            return null;
482	        }
483	        return this.clinicService.findAllOwners().stream()
484	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
485	            .filter(existing -> postcode.equals(existing.getPostcode()))
486	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
487	            .min(java.util.Comparator.comparing(Owner::getId))
488	            .orElse(null);
489	    }
490	
491	    /**
492	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
493	     * request to create another owner in it is rejected as a conflict.
494	     */
495	    private static final int MAX_OWNERS_PER_CITY = 50;
496	
497	    /**
498	     * Count the existing owners registered in the given city, compared case-insensitively (as in
499	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
500	     * reflects the owners that already existed at creation time.
501	     */
502	    private int countOwnersInCity(String city) {
503	        return (int) this.clinicService.findAllOwners().stream()
504	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
505	            .count();
506	    }
507	
508	    /**
509	     * The maximum number of owners that may be created on a single day. Once this many owners
510	     * already carry a given day's registration date, a request to create another owner that day is
511	     * rejected with a 429.
512	     */
513	    private static final int MAX_OWNERS_PER_DAY = 100;
514	
515	    /**
516	     * The number of owners that may be created on a single day before the bulk-signup warning is
517	     * flagged. Once more than this many owners already carry a given day's registration date, a
518	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
519	     */
520	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
521	
522	    /**
523	     * Count the existing owners whose registration date is the given day. Called before the new
524	     * owner is saved, so the returned value reflects the owners that already existed at creation
525	     * time.
526	     */
527	    private int countOwnersRegisteredOn(LocalDate date) {
528	        return (int) this.clinicService.findAllOwners().stream()
529	            .filter(existing -> date.equals(existing.getRegistrationDate()))
530	            .count();
531	    }
532	
533	    /**
534	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
535	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
536	     * supplied or defaulted) always falls on a business day.
537	     */
538	    private static LocalDate toBusinessDay(LocalDate date) {
539	        return switch (date.getDayOfWeek()) {
540	            case SATURDAY -> date.plusDays(2);
541	            case SUNDAY -> date.plusDays(1);
542	            default -> date;
543	        };
544	    }
545	
546	    /**
547	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
548	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
549	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
550	     */
551	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
552	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
553	    }
554	
555	    /**
556	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
557	     */
558	    private static String hash8(String input) {
559	        try {
560	            byte[] digest = MessageDigest.getInstance("SHA-256")
561	                .digest(input.getBytes(StandardCharsets.UTF_8));
562	            StringBuilder sb = new StringBuilder(digest.length * 2);
563	            for (byte b : digest) {
564	                sb.append(String.format("%02x", b));
565	            }
566	            return sb.substring(0, 8).toUpperCase();
567	        }
568	        catch (NoSuchAlgorithmException e) {
569	            throw new IllegalStateException("SHA-256 not available", e);
570	        }
571	    }
572	
573	    /**
574	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
575	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
576	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
577	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
578	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
579	     * always agree.
580	     */
581	    private static String deriveRegion(String postcode, String city) {
582	        if (postcode != null && postcode.matches("\\d{4}")) {
583	            int value = Integer.parseInt(postcode);
584	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
585	                int[] range = entry.getValue();
586	                if (value >= range[0] && value <= range[1]) {
587	                    return entry.getKey();
588	                }
589	            }
590	        }
591	        if (city == null) {
592	            return "UNKNOWN";
593	        }
594	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
595	    }
596	
597	    /**
598	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
599	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
600	     * and accepts any 4-digit postcode.
601	     */
602	    private static final Map<String, String> CITY_REGION = Map.of(
603	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
604	
605	    /**
606	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
607	     * Each entry is a two-element {@code {low, high}} array.
608	     */
609	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
610	        "NSW", new int[] {2000, 2099},
611	        "VIC", new int[] {3000, 3099},
612	        "QLD", new int[] {4000, 4099});
613	
614	    /**
615	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
616	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
617	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
618	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
619	     * 4-digit postcode. A malformed or out-of-range postcode throws an
620	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
621	     */
622	    private static void validatePostcode(String city, String postcode) {
623	        if (postcode == null || postcode.isEmpty()) {
624	            return;
625	        }
626	        if (!postcode.matches("\\d{4}")) {
627	            throw new InvalidOwnerFieldsException(List.of("postcode"));
628	        }
629	        String region = city == null ? null : CITY_REGION.get(city);
630	        if (region == null) {
631	            return;
632	        }
633	        int[] range = REGION_POSTCODES.get(region);
634	        int value = Integer.parseInt(postcode);
635	        if (value < range[0] || value > range[1]) {
636	            throw new InvalidOwnerFieldsException(List.of("postcode"));
637	        }
638	    }
639	
640	    /**
641	     * Required national-number length for each E.164 country calling code we validate: a
642	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
643	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
644	     */
645	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
646	        "1", 10,
647	        "61", 9);
648	
649	    /**
650	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
651	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
652	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
653	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
654	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
655	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
656	     * rejected with a 400.
657	     */
658	    private static String toE164(String raw) {
659	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
660	        boolean hasCountryCode = cleaned.startsWith("+");
661	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
662	        if (!digits.matches("\\d+")) {
663	            throw new InvalidOwnerFieldsException(List.of("telephone"));
664	        }
665	        if (!hasCountryCode) {
666	            if (digits.startsWith("0")) {
667	                digits = digits.substring(1);
668	            }
669	            digits = "61" + digits;
670	        }
671	        if (digits.length() < 8 || digits.length() > 15) {
672	            throw new InvalidOwnerFieldsException(List.of("telephone"));
673	        }
674	        // For a recognised country code, the national number (the digits after the code) must be
675	        // exactly the expected length for that country. Match the longest known code so a shorter
676	        // code that is a prefix of another cannot mask it.
677	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
678	            if (digits.length() <= codeLength) {
679	                continue;
680	            }
681	            String countryCode = digits.substring(0, codeLength);
682	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
683	            if (requiredNationalLength != null) {
684	                if (digits.length() - codeLength != requiredNationalLength) {
685	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
686	                }
687	                break;
688	            }
689	        }
690	        return "+" + digits;
691	    }
692	
693	    /**
694	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
695	     * and a domain with at least one dot-separated label, none of which contain whitespace or
696	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
697	     */
698	    private static final Pattern EMAIL_PATTERN =
699	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
700	
701	    /**
702	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
703	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
704	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
705	     * 400. A valid address is returned lower-cased.
706	     */
707	    private static String normalizeEmail(String email) {
708	        if (email == null || email.isEmpty()) {
709	            return null;
710	        }
711	        String trimmed = email.trim();
712	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
713	            throw new InvalidOwnerFieldsException(List.of("email"));
714	        }
715	        return trimmed.toLowerCase();
716	    }
717	}
